_G.equateXP = function(xp) {
    return Math.floor(xp + 300 * Math.pow(2, xp / 7));
};

_G.LevelToXP = function(level) {
    var xp = 0;

    for (var i = 1; i < level; i++)
        xp += _G.equateXP(i);

    return Math.floor(xp / 4);
};

_G.XPToLevel = function(xp) {
    var level = 1;

    while (_G.LevelToXP(level) < xp)
        level++;

    return level;
};

