                                    ply.AddItem(ply.container.Container[ply.conSlot].item, 1);

                                    ply.ShowNotify('Bought ' + _G.items[ply.container.Container[ply.conSlot].item].name + ' for ' + itemPrice + ' ' + _G.items[currency].name, 2500);

