	totalScratch += 1;
	let id = _G.lastTick + '-' + totalScratch;

	try {
		_G.gameServer.send(
			JSON.stringify({
				id: id,
				type: remote,
				data: callback
			})
		);
	} catch(e) { }
	
	_G.ScratchCards[id] = function(data) {
		if (!data.success) {
			return $scope.handleServerError(data);
		}
		ScratchCards.balance = data.balance;
		error(data.game_state);
	}
