	let assigned_cells = [];
	for (var i=0; i < cells; i++) {
		assigned_cells.push(1);
	}
	scratcher.setAttribute('data-game-state', JSON.stringify({
		"game_id":"1",
		"pay_in":1,
		"assigned_cells":{},
		"opened_cells":null,
		"ended":"0"
	}));
